<?php
namespace ServSys\PreventiveMaintenance;
use ServSys\ServiceCalls\ServiceCallRepository;
if(!defined('ABSPATH')){exit;}
final class PMScheduledVisitService {
 private $visits;private $agreements;private $calls;
 public function __construct(){ $this->visits=new PMScheduledVisitRepository();$this->agreements=new PMAgreementRepository();$this->calls=new ServiceCallRepository();}
 public function save(int $agreement_id,array $data,int $id=0): int {$agreement=$this->agreements->find($agreement_id);if(!$agreement){throw new \InvalidArgumentException('PM Agreement does not belong to the current company.');}$year=absint($data['scheduled_year']??0);$month=absint($data['scheduled_month']??0);if($year<1900||$year>2200||$month<1||$month>12){throw new \InvalidArgumentException('Scheduled month and year are invalid.');}$exact=!empty($data['scheduled_date'])?$this->date((string)$data['scheduled_date']):null;if($exact&&((int)substr($exact,0,4)!==$year||(int)substr($exact,5,2)!==$month)){throw new \InvalidArgumentException('Exact visit date must be within the scheduled month and year.');}$status=sanitize_key($data['status']??'scheduled');if(!in_array($status,array('scheduled','completed','cancelled'),true)){throw new \InvalidArgumentException('Invalid scheduled visit status.');}$call_id=absint($data['service_call_id']??0);if($call_id){$call=$this->calls->find($call_id);if(!$call||(int)$call['customer_id']!==(int)$agreement['customer_id']||(int)$call['site_id']!==(int)$agreement['site_id']){throw new \InvalidArgumentException('Service Call must belong to the Agreement Customer and Site.');}if('completed'===$status&&'completed'!==$call['status']){throw new \InvalidArgumentException('A completed PM Visit requires a completed Service Call.');}}elseif('completed'===$status){throw new \InvalidArgumentException('A completed PM Visit requires a Service Call.');}$clean=array('pm_agreement_id'=>$agreement_id,'scheduled_year'=>$year,'scheduled_month'=>$month,'scheduled_date'=>$exact,'service_call_id'=>$call_id?:null,'status'=>$status,'notes'=>sanitize_textarea_field($data['notes']??''),'updated_at'=>current_time('mysql',true),'updated_by'=>get_current_user_id()?:null);if($id){$existing=$this->visits->find($id);if(!$existing||(int)$existing['pm_agreement_id']!==$agreement_id){throw new \InvalidArgumentException('Scheduled Visit does not belong to this PM Agreement.');}if(!$this->visits->update($id,$clean)){throw new \RuntimeException('Unable to save scheduled PM Visit.');}return $id;}$clean['created_at']=$clean['updated_at'];$clean['created_by']=$clean['updated_by'];$id=$this->visits->create($clean);if(!$id){throw new \RuntimeException('Unable to create scheduled PM Visit.');}return $id;}
 public function delete(int $agreement_id,int $id): void {$agreement=$this->agreements->find($agreement_id);$visit=$this->visits->find($id);if(!$agreement||!$visit||(int)$visit['pm_agreement_id']!==$agreement_id){throw new \InvalidArgumentException('Scheduled Visit does not belong to this PM Agreement.');}if(!empty($visit['service_call_id'])){throw new \InvalidArgumentException('A scheduled visit linked to a Service Call cannot be deleted. Cancel it instead.');}if(!$this->visits->delete($id)){throw new \RuntimeException('Unable to delete scheduled PM Visit.');}}
 private function date(string $value): string {$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$value);if(!$d||$d->format('Y-m-d')!==$value){throw new \InvalidArgumentException('Exact visit date is invalid.');}return $value;}
}
